using Diten.DecisionIntelligenceService.Domain.Modules.OutcomeTracking;
namespace Diten.DecisionIntelligenceService.Application.Modules.OutcomeTracking;
public static class AuthorizationManifest{public static readonly IReadOnlyDictionary<string,string> Operations=new Dictionary<string,string>{{"outcome-tracking.outcomes.read","decision-intelligence.outcomes.read"},{"outcome-tracking.outcomes.create","decision-intelligence.outcomes.create"},{"outcome-tracking.outcomes.publish-version","decision-intelligence.outcomes.version"},{"outcome-tracking.outcomes.retire","decision-intelligence.outcomes.version"},{"outcome-tracking.measurements.append","decision-intelligence.measurements.append"},{"outcome-tracking.measurements.correct","decision-intelligence.measurements.correct"},{"outcome-tracking.decision-links.create","decision-intelligence.decision-links.manage"},{"outcome-tracking.decision-links.retire","decision-intelligence.decision-links.manage"},{"outcome-tracking.outcome-references.validate","decision-intelligence.outcome-references.validate"}};}
public sealed record MutationScope(Guid TenantId,Guid ActorId,string Operation,string Key,string Hash); public sealed record MutationResult(int Status,string Value); public enum Participant{Aggregate,Version,Measurement,Link,Receipt,AuditIntent,Outbox} public enum Reconciliation{Matching,Conflicting,ConfirmedAbsent,Indeterminate}
public interface IOutcomeTransaction{MutationResult Execute(MutationScope scope,Func<MutationResult> mutation,IReadOnlySet<Participant> participants,Participant? failAt=null);MutationResult Reconcile(MutationScope scope,Reconciliation result);}
public static class MeasurementRules
{
 public static void NoOverlap(IEnumerable<OutcomeMeasurement> xs,OutcomeMeasurement c){if(xs.Any(x=>x.TenantId==c.TenantId&&x.OutcomeId==c.OutcomeId&&x.OutcomeVersionId==c.OutcomeVersionId&&x.SupersedesMeasurementId is null&&c.SupersedesMeasurementId is null&&x.Period.Overlaps(c.Period)))throw new DomainConflictException();}
 public static void CorrectionHead(IReadOnlyCollection<OutcomeMeasurement> xs,OutcomeMeasurement c){if(c.SupersedesMeasurementId is null)throw new DomainConflictException();var t=xs.SingleOrDefault(x=>x.Id==c.SupersedesMeasurementId);if(t is null||t.Id==c.Id||t.TenantId!=c.TenantId||t.OutcomeId!=c.OutcomeId||t.OutcomeVersionId!=c.OutcomeVersionId||t.Period!=c.Period||xs.Any(x=>x.SupersedesMeasurementId==t.Id)||CreatesCycle(xs,c))throw new DomainConflictException();}
 private static bool CreatesCycle(IReadOnlyCollection<OutcomeMeasurement> xs,OutcomeMeasurement c){var seen=new HashSet<Guid>{c.Id};var id=c.SupersedesMeasurementId;while(id is not null){if(!seen.Add(id.Value))return true;id=xs.SingleOrDefault(x=>x.Id==id.Value)?.SupersedesMeasurementId;}return false;}
}
public sealed record ObservationProjection(Guid TenantId,Guid OutcomeId,Guid OutcomeVersionId,ObservationStatus Status);
public static class ObservationProjector
{
 public static ObservationProjection Project(IEnumerable<OutcomeMeasurement> xs,Guid tenantId,Guid outcomeId,Guid versionId,DateOnly asOf,int freshness){var scoped=xs.Where(x=>x.TenantId==tenantId&&x.OutcomeId==outcomeId&&x.OutcomeVersionId==versionId).ToArray();var heads=scoped.Where(x=>!scoped.Any(y=>y.SupersedesMeasurementId==x.Id)).ToArray();var status=heads.Length==0?ObservationStatus.NoObservation:heads.Max(x=>x.Period.End)>=asOf.AddDays(-freshness)?ObservationStatus.Current:ObservationStatus.Stale;return new(tenantId,outcomeId,versionId,status);}
 public static ObservationProjection Rebuild(IEnumerable<OutcomeMeasurement>x,Guid t,Guid o,Guid v,DateOnly d,int f)=>Project(x,t,o,v,d,f);
}
